CREATE TABLE IF NOT EXISTS cars (id BIGINT AUTO_INCREMENT PRIMARY KEY, ownerId BIGINT NOT NULL, brand VARCHAR(255) NOT NULL, `type` VARCHAR(255) NOT NULL, licensePlate VARCHAR(255) NOT NULL, pricePerDay DOUBLE PRECISION NOT NULL, pickupId BIGINT NOT NULL, dropOffId BIGINT NOT NULL, pictures JSON NULL, isAvailable BOOLEAN DEFAULT FALSE NOT NULL, CONSTRAINT fk_cars_ownerId__id FOREIGN KEY (ownerId) REFERENCES users(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_cars_pickupId__id FOREIGN KEY (pickupId) REFERENCES locations(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_cars_dropOffId__id FOREIGN KEY (dropOffId) REFERENCES locations(id) ON DELETE RESTRICT ON UPDATE RESTRICT);

